73	    // Find a package in workspace from a specifier
74	    fn find_package(
75	        &self,
76	        specifier: WorkspacePackageSpecifier,
77	    ) -> Option<(PackageName, &PackageInfo)> {
78	        match specifier {
79	            WorkspacePackageSpecifier::Alias(name) => {
80	                // TODO implement borrowing for workspaces to allow for zero copy queries
81	                let package_name = PackageName::Other(name.to_string());
82	                let info = self.workspaces.get(&package_name)?;
83	                Some((package_name, info))
84	            }
85	            WorkspacePackageSpecifier::Path(path) => {
86	                let package_path = self.workspace_dir.join_unix_path(path);
87	                // There's a chance that the user provided path could escape the root, in which
88	                // case we don't support packages outside of the workspace.
89	                // Pnpm also doesn't support this so we defer to them to provide the error
90	                // message.
91	                let package_path = AnchoredSystemPathBuf::new(self.repo_root, package_path).ok()?;
92	                let (name, info) = self.workspace(&package_path).or_else(|| {
93	                    // Yarn4 allows for workspace root relative paths
94	                    let package_path = self.repo_root.join_unix_path(path);
95	                    let package_path =
96	                        AnchoredSystemPathBuf::new(self.repo_root, package_path).ok()?;
97	                    self.workspace(&package_path)
98	                })?;
